import{_ as t,o as r,c as s,a0 as a}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"Architecture Decision Records","description":"","frontmatter":{},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md","lastUpdated":1792140001000}'),o={name:"adr/index.md"};function n(d,e,i,l,h,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture-decision-records" tabindex="-1">Architecture Decision Records <a class="header-anchor" href="#architecture-decision-records" aria-label="Permalink to &quot;Architecture Decision Records&quot;">​</a></h1><p>The decisions that shape this project. Each ADR records the context, the chosen option, and the options that were considered.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Decision</th></tr></thead><tbody><tr><td><a href="/pi-extensions/adr/0001-embed-codegraph-in-process.html">0001</a></td><td>Embed codegraph in-process, not via daemon or CLI.</td></tr><tr><td><a href="/pi-extensions/adr/0002-per-worktree-index-seeded-from-sibling.html">0002</a></td><td>Per-worktree index, seeded from a sibling worktree.</td></tr><tr><td><a href="/pi-extensions/adr/0003-named-project-roots-for-dependency-sources.html">0003</a></td><td>Named project roots for dependency sources.</td></tr><tr><td><a href="/pi-extensions/adr/0004-context-window-cap-via-provider-reregistration.html">0004</a></td><td>Context window cap via provider re-registration.</td></tr><tr><td><a href="/pi-extensions/adr/0005-quota-owns-chatgpt-token-refresh.html">0005</a></td><td>Quota extension refreshes the ChatGPT token itself.</td></tr><tr><td><a href="/pi-extensions/adr/0006-model-router-resumes-via-user-message.html">0006</a></td><td>Model router resumes a quota-halted turn with a synthetic user message.</td></tr><tr><td><a href="/pi-extensions/adr/0007-sync-uses-oauth-device-flow-with-expiring-tokens.html">0007</a></td><td>Sync authenticates with the OAuth device flow and expiring tokens.</td></tr><tr><td><a href="/pi-extensions/adr/0008-usage-report-derived-from-session-scan.html">0008</a></td><td>Usage reports are derived from session files, not a stored index.</td></tr><tr><td><a href="/pi-extensions/adr/0009-usage-events-counted-once-per-distinct-line.html">0009</a></td><td>Usage events are counted once, keyed by the full session line.</td></tr><tr><td><a href="/pi-extensions/adr/0010-gist-names-encode-paths-empty-files-absent.html">0010</a></td><td>Gist names percent-encode sync paths, and empty files are absent.</td></tr><tr><td><a href="/pi-extensions/adr/0011-pruning-is-a-request-projection.html">0011</a></td><td>Pruning is a request-level projection; the session file is the store.</td></tr><tr><td><a href="/pi-extensions/adr/0012-resource-toggles-write-native-settings-patterns.html">0012</a></td><td>Resource toggles write the native settings override patterns.</td></tr><tr><td><a href="/pi-extensions/adr/0013-skill-tree-tracks-upstream-sources-with-per-source-pins.html">0013</a></td><td>The skill tree tracks upstream sources with per-source pins.</td></tr><tr><td><a href="/pi-extensions/adr/0014-tool-usage-counts-cached-session-scan.html">0014</a></td><td>Tool usage counts are derived from a session scan with a per-file stat-keyed cache.</td></tr><tr><td><a href="/pi-extensions/adr/0015-compression-is-a-request-time-view.html">0015</a></td><td>Compression is a request-time view; the compressed form is text.</td></tr><tr><td><a href="/pi-extensions/adr/0016-dependency-indexes-build-on-first-query.html">0016</a></td><td>Dependency indexes build on first query, with streamed progress.</td></tr><tr><td><a href="/pi-extensions/adr/0017-docs-screenshots-render-by-capture-pipeline.html">0017</a></td><td>Docs screenshots render by a capture pipeline; none is taken by hand.</td></tr><tr><td><a href="/pi-extensions/adr/0018-pruning-engagement-is-sticky.html">0018</a></td><td>Pruning engagement is sticky for the session; it holds until a reset.</td></tr><tr><td><a href="/pi-extensions/adr/0019-llama-refresh-self-heals-the-fallback-window.html">0019</a></td><td>The fallback window self-heals via a one-shot re-resolution after the model&#39;s wake.</td></tr><tr><td><a href="/pi-extensions/adr/0020-edit-assist-corrects-by-mutating-tool-call-input.html">0020</a></td><td>Edit assist corrects failing edit calls by mutating tool input; it never writes files.</td></tr><tr><td><a href="/pi-extensions/adr/0021-ctx-shows-the-base-prompt-as-split-rows.html">0021</a></td><td>/ctx shows the default base prompt as split rows: boilerplate, snippets, one row per guideline.</td></tr><tr><td><a href="/pi-extensions/adr/0022-ctx-flags-guidelines-that-duplicate-tool-descriptions.html">0022</a></td><td>/ctx flags guidelines that largely restate a sent tool description, with a conservative substring rule.</td></tr><tr><td><a href="/pi-extensions/adr/0023-background-jobs-keep-state-on-disk-per-job.html">0023</a></td><td>Background jobs keep state on disk, per job: the exit code is written by a shell wrapper, and the tools are active by default.</td></tr><tr><td><a href="/pi-extensions/adr/0024-bash-bg-tool-row-shows-the-plain-command-line.html">0024</a></td><td>The bash_bg tool row shows the plain command line, with no background marker.</td></tr><tr><td><a href="/pi-extensions/adr/0025-safe-branch-summary-replaces-the-built-in.html">0025</a></td><td>The Safe branch summary replaces the built-in branch summarizer and budgets against the Effective window divided by the Inflation factor.</td></tr><tr><td><a href="/pi-extensions/adr/0026-output-limits-bound-results-in-the-tool-result-hook.html">0026</a></td><td>Output limits bounds tool results downward in the <code>tool_result</code> hook; it is one-directional and lossless or it does not cut.</td></tr><tr><td><a href="/pi-extensions/adr/0027-the-live-catalog-comparison-heals-the-window.html">0027</a></td><td>Llama refresh heals any window drift by comparing the catalog before and after one forced refresh, at two fixed heal moments; the fallback sentinel is no longer the gate.</td></tr><tr><td><a href="/pi-extensions/adr/0028-output-starvation-guard-refuses-a-collapsed-output-budget.html">0028</a></td><td>The output-starvation guard judges one request&#39;s output budget against the Effective window, keyed on pi&#39;s own clamp: it refuses a budget at pi&#39;s saturated floor (one line and the run&#39;s abort, at most once per turn), and it fits an overrunning budget to the room the Corrected estimate leaves. The guard never raises a budget.</td></tr><tr><td><a href="/pi-extensions/adr/0029-package-toggles-write-packages-array-filters.html">0029</a></td><td>Package toggles write the packages-array filter, not resource-array patterns; the old resource-array write is a no-op that heals itself on the next toggle.</td></tr><tr><td><a href="/pi-extensions/adr/0030-resource-descriptions-read-from-the-source-file.html">0030</a></td><td>Resource descriptions are read from the source file: frontmatter for a skill or prompt template, the leading block comment for an extension, nothing for a theme.</td></tr><tr><td><a href="/pi-extensions/adr/0031-a-same-model-re-select-is-read-from-the-transcript.html">0031</a></td><td>A same-model re-select is read from the transcript&#39;s <code>model_change</code> entry at the next turn start, with a self-guard so the extension&#39;s own re-apply never re-arms itself.</td></tr><tr><td><a href="/pi-extensions/adr/0032-skill-migrate-runs-sequential-migrations-with-a-committed-changelog.html">0032</a></td><td>skill-migrate runs sequential repo-structure migrations; each target repo commits an append-only changelog that audits every completed step, and git is the rollback layer.</td></tr><tr><td><a href="/pi-extensions/adr/0033-skill-command-normalizes-the-injected-skill-command-separator.html">0033</a></td><td>Skill command rewrites a newline-separated <code>/skill:</code> command to the single-space form in the input event; pi keeps owning the expansion.</td></tr><tr><td><a href="/pi-extensions/adr/0034-the-vendored-antislop-copy-is-edited-for-a-tracked-tree.html">0034</a></td><td>The vendored antislop core is edited in two places only: its self-install and self-update sections are cut, and an unresolved usage mode defaults to <code>during</code> instead of asking.</td></tr><tr><td><a href="/pi-extensions/adr/0035-the-skill-tool-loads-referenced-skills-by-name.html">0035</a></td><td>The skill tool loads a referenced skill by name against pi&#39;s own registry, so the model never re-types a skill&#39;s install path.</td></tr><tr><td><a href="/pi-extensions/adr/0036-a-job-dies-as-a-process-group.html">0036</a></td><td>A job is one process group, stopped with a group signal, and its record covers it while any of its processes is alive; the shells trap no signals.</td></tr><tr><td><a href="/pi-extensions/adr/0037-a-job-dies-with-the-agent-process.html">0037</a></td><td>A job&#39;s lifetime is bounded by the agent process: the wrapper watches the agent&#39;s pid and stops the job&#39;s process group when the agent dies. Supersedes the outlive-the-session decision of ADR 0023.</td></tr><tr><td><a href="/pi-extensions/adr/0038-tool-row-headers-wrap-pi-tool-renderers.html">0038</a></td><td>Tool row headers wrap pi&#39;s tool renderers: one resolver prepends the tool name to whatever pi or another extension would draw, for every tool, with no setting.</td></tr><tr><td><a href="/pi-extensions/adr/0039-printed-command-lines-are-runnable-as-printed.html">0039</a></td><td>Every command line a tool prints is runnable as printed from any working directory: the path is derived from the module&#39;s own location, never hardcoded, never a PATH probe, never an env var the user must set.</td></tr><tr><td><a href="/pi-extensions/adr/0040-the-diagnostics-loop-is-the-job-and-v1-is-read-only.html">0040</a></td><td>The LSP extension&#39;s job is the Post-edit diagnostics loop, not navigation; v1 is read-only, and the turn-end message never requests a continuation.</td></tr><tr><td><a href="/pi-extensions/adr/0041-the-lsp-client-is-in-process-on-the-official-protocol-packages.html">0041</a></td><td>The LSP client is in-process on <code>vscode-jsonrpc</code> plus <code>vscode-languageserver-protocol</code>, not an MCP bridge and not a hand-rolled framing.</td></tr><tr><td><a href="/pi-extensions/adr/0042-the-watcher-discovers-and-the-stat-check-verifies.html">0042</a></td><td>The watcher discovers changed paths and a stat check verifies currency; a watcher event is never proof, and a degraded watcher falls back to a stat pass plus a bounded git sweep.</td></tr><tr><td><a href="/pi-extensions/adr/0043-language-servers-are-lazy-per-root-and-never-shared.html">0043</a></td><td>Language servers are lazy, one per (language, root) pair, bounded to four per session, and never shared across sessions.</td></tr><tr><td><a href="/pi-extensions/adr/0044-the-typescript-7-native-server-is-found-per-root.html">0044</a></td><td>The TypeScript 7 native server is found per root: the project&#39;s own typescript@7 wins ahead of every PATH binary, and a PATH tsc only counts when it reports version 7 or newer.</td></tr></tbody></table>',3)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
